from pathlib import Path
p=Path('scripts/_tmp_high_reuse_deep_v2.py')
s=p.read_text(encoding='utf-8')
pos=s.index('print("roots"')
header=s[:pos]
body=s[pos:]
insert='''\n# Reconstruct first predecessor edges and direct-call caller records for every CFG-start and every candidate function.\npred = {}\nroot_of = {}\nq = collections.deque((r, r) for r in sorted(set(exp_roots + [0x0e5dc690, 0x00036790, 0x000367a0])))\nprocessed = set()\nwhile q:\n    start, root = q.popleft()\n    key = (start, root)\n    if key in processed or not is_exec(start): continue\n    processed.add(key)\n    for x in disasm(start, maxlen=0x10000):\n        ins = x.address - IB\n        root_of.setdefault(ins, set()).add(root)\n        if ins != start and ins not in pred: pred[ins] = start\n        m = x.mnemonic\n        if m in ('ret', 'retn', 'iret', 'iretd', 'ud2', 'int3'): break\n        if m == 'call':\n            nxt = ins + x.size\n            if is_exec(nxt) and nxt not in pred:\n                pred[nxt] = ins\n                q.append((nxt, root))\n            if x.operands and x.operands[0].type == CS_OP_IMM:\n                t = x.operands[0].imm - IB\n                if is_exec(t): q.append((t, t))\n        elif m.startswith('j'):\n            if x.operands and x.operands[0].type == CS_OP_IMM:\n                t = x.operands[0].imm - IB\n                if is_exec(t) and t not in pred:\n                    pred[t] = ins\n                if is_exec(t): q.append((t, root))\n            if m != 'jmp':\n                nxt = ins + x.size\n                if is_exec(nxt) and nxt not in pred:\n                    pred[nxt] = ins\n                    q.append((nxt, root))\n        else:\n            nxt = ins + x.size\n            if is_exec(nxt) and nxt not in pred:\n                pred[nxt] = ins\n                q.append((nxt, root))\n\ndef cfg_path(target, limit=64):\n    out = []\n    seen = set()\n    cur = target\n    while cur is not None and cur in pred and len(out) < limit:\n        if cur in seen: break\n        seen.add(cur); out.append(cur); cur = pred[cur]\n    out.reverse()\n    return out\n\ndef direct_call_refs(client):\n    out = []\n    for s in SECS:\n        if s['name'] == '.tvm0' or not (s['ch'] & 0x20000000): continue\n        b = D[s['pr']:s['pr'] + s['rs']]\n        for j in range(len(b) - 5):\n            if b[j] == 0xe8 and s['va'] + j + 5 + struct.unpack_from('<i', b, j + 1)[0] == client:\n                out.append(s['va'] + j)\n    return sorted(set(out))\n\n'''
body=body.replace('refs = raw_refs()', insert+'refs = raw_refs()')
body=body.replace("direct_e8_callers=' '.join('0x%08X' % v for v in sorted(set(e8refs.get(st, [])))) if st is not None else '',\n                     direct_e8_caller_count=str(len(set(e8refs.get(st, [])))) if st is not None else '0',",
"direct_e8_callers=' '.join('0x%08X' % v for v in direct_call_refs(st)) if st is not None else '',\n                     direct_e8_caller_count=str(len(direct_call_refs(st))) if st is not None else '0',")
old="                     direct_e8_caller_count=str(len(direct_call_refs(st))) if st is not None else '0',\n                     pre64="
new="                     direct_e8_caller_count=str(len(direct_call_refs(st))) if st is not None else '0',\n                     cfg_path=(' '.join('0x%08X' % v for v in cfg_path(rva)) if rva in pred else ''),\n                     cfg_owner_roots=' '.join('0x%08X' % v for v in sorted(root_of.get(rva, set()))),\n                     pre64="
body=body.replace(old,new)
p.write_text(header+body,encoding='utf-8')
print('written')
